import type { Factors, Family } from "./lib/co2.ts";
import { costUsd, parsePrices } from "./lib/cost.ts";
import { DETAIL_SVG_HEIGHT, periodDetail, splitBarSvg, swatchSvg } from "./lib/detail.ts";
import type { Prices } from "./lib/cost.ts";
import {
  answerLine,
