  detailCoverage,
  detailLine,
  METHODOLOGY_URL,
  methodologyLabel,
  detailHover,
  detailTotalLine,
  detailWaitText,
  kindLabel,
  buildAnswerCo2,
  cardButtonLabel,
  cardDraftBusy,
  cardFillFailed,
  cardReadyText,
  changePercent,
  colorNote,
  commandDescription,
  compareText,
  costText,
  currentLine,
  dateLabel,
  detectLang,
  emptyRangeText,
  carValue,
  carTag,
  fromLabel,
  hasLangVariable,
  isCarbonStatusLine,
  languageSetting,
  contextText,
  moreAgentsText,
  subagentsAlt,
  subagentTitle,
  mascotAlt,
  scaleAlt,
  noHistoryText,
  otherProjectsLine,
  paneHint,
  paneTitle,
  paneUnplaced,
  projectBarLine,
  pushHistory,
  rangeLabel,
  sessionLine,
  showLabel,
  stripesAlt,
  stripesCaption,
  stripesWaitText,
  stripeTitle,
  toLabel,
  waitingText,
  welcomeText,
} from "./lib/format.ts";
import type { Lang } from "./lib/format.ts";
import { lineEntry } from "./lib/lines.ts";
import {
